pub fn rotate_right(list: &Vec<u32>, n: usize) -> Vec<u32> {
    let len = list.len();
    debug_assert!(len > 0, "input list must be non-empty");

    let k = n % len;      // effective right rotation
    let s = len - k;      // split point per problem statement

    let mut out = Vec::with_capacity(len);
    out.extend_from_slice(&list[s..len]);
    out.extend_from_slice(&list[0..s]);
    out
}

